export enum AppView {
  DASHBOARD = 'DASHBOARD',
  USER_MANAGEMENT = 'USER_MANAGEMENT',
  TERMINAL_MONITOR = 'TERMINAL_MONITOR',
  FAULT_TICKETS = 'FAULT_TICKETS',
  OTA_MANAGEMENT = 'OTA_MANAGEMENT',
  AUDIT_LOGS = 'AUDIT_LOGS',
  SYSTEM_CONFIG = 'SYSTEM_CONFIG'
}

export interface User {
  id: string;
  username: string;
  phone: string;
  boundVehicle: string;
  appVersion: string;
  serviceStatus: 'Active' | 'Expired' | 'Pending';
  registerDate: string;
}

export interface VehicleTerminal {
  id: string;
  vin: string;
  status: 'Online' | 'Offline' | 'Warning';
  signal: number; // 0-100
  faultCode: string | null;
  lastHeartbeat: string;
  location: string;
}

export interface FaultTicket {
  id: string;
  vin: string;
  type: string;
  severity: 'High' | 'Medium' | 'Low';
  status: 'Open' | 'Processing' | 'Closed';
  createdAt: string;
  description: string;
}

export interface OTATask {
  id: string;
  version: string;
  targetModel: string;
  progress: number;
  status: 'Pending' | 'In Progress' | 'Completed' | 'Failed';
  startTime: string;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { AppView } from './types';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import DashboardView from './components/DashboardView';
import UserManagementView from './components/UserManagementView';
import TerminalMonitorView from './components/TerminalMonitorView';
import FaultTicketView from './components/FaultTicketView';
import OTAManagementView from './components/OTAManagementView';
import AuditLogView from './components/AuditLogView';
import Login from './components/Login';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentView, setCurrentView] = useState<AppView>(AppView.DASHBOARD);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);

  if (!isAuthenticated) {
    return <Login onLogin={() => setIsAuthenticated(true)} />;
  }

  const renderContent = () => {
    switch (currentView) {
      case AppView.DASHBOARD:
        return <DashboardView />;
      case AppView.USER_MANAGEMENT:
        return <UserManagementView />;
      case AppView.TERMINAL_MONITOR:
        return <TerminalMonitorView />;
      case AppView.FAULT_TICKETS:
        return <FaultTicketView />;
      case AppView.OTA_MANAGEMENT:
        return <OTAManagementView />;
      case AppView.AUDIT_LOGS:
        return <AuditLogView />;
      default:
        return <DashboardView />;
    }
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-50">
      <Sidebar 
        currentView={currentView} 
        onViewChange={setCurrentView} 
        isCollapsed={isSidebarCollapsed}
        toggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
      />

      <div className="flex flex-col flex-1 min-w-0 overflow-hidden">
        <Header 
          currentViewName={currentView.replace('_', ' ')} 
          onLogout={() => setIsAuthenticated(false)}
        />

        <main className="flex-1 overflow-y-auto p-6 scroll-smooth">
          {renderContent()}
        </main>
      </div>
    </div>
  );
};

export default App;

